using AquaGuardAI.Models;
namespace AquaGuardAI.Services;
public class PredictionService { public PredictionResult Predict(WaterSample s){int n=8;var f=new List<string>();if(s.Ph<6.5||s.Ph>8.5){n+=18;f.Add("pH outside illustrative reference band");}if(s.Turbidity>5){n+=22;f.Add("Elevated turbidity");}else if(s.Turbidity>1){n+=8;f.Add("Moderate turbidity");}if(s.Tds>500){n+=16;f.Add("High total dissolved solids");}if(s.Chlorine<.2){n+=20;f.Add("Low residual chlorine");}if(s.Temperature>30){n+=7;f.Add("Higher water temperature");}if(s.ReportedCases>=10){n+=20;f.Add("Elevated symptom reports");}else if(s.ReportedCases>=5){n+=10;f.Add("Increasing symptom reports");}n=Math.Clamp(n,0,100);return new(n,n>=65?"High":n>=35?"Moderate":"Low",f.Count==0?new[]{"No major demo threshold flags"}:f.ToArray(),n>=65?"Arrange confirmatory sampling and notify authorized water-quality and public-health teams.":n>=35?"Repeat testing and review treatment and distribution points.":"Continue routine sampling and community awareness.");} }